import{_ as a,a as t,b as l,c as r}from"./chunks/907f9404bcd155e2c4e1.Ci88IA8d.js";import{_ as i,C as s,o as n,c as u,j as e,a as c,E as m,a5 as h}from"./chunks/framework.DNkHA0lr.js";const Y=JSON.parse('{"title":"社交媒体上实现增长的最佳途径（从零粉丝和零经验开始）","description":"","frontmatter":{"title":"社交媒体上实现增长的最佳途径（从零粉丝和零经验开始）","originalTitle":"The Best Way To Grow On Social Media (From Zero Followers & Experience)","date":"2024-04-27","originalUrl":"https://thedankoe.com/letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience/","minutes":12,"sourceHash":"211e5ca5a2a453cfa59f42ebb0f8ab871af2cf2c2db1a54bb7db9769065f51c4","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience/"}]]},"headers":[],"relativePath":"letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience.md","filePath":"letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience.md"}'),d={name:"letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience.md"};function b(f,p,_,T,w,g){const o=s("ArticleMeta");return n(),u("div",null,[p[0]||(p[0]=e("h1",{id:"社交媒体上实现增长的最佳途径-从零粉丝和零经验开始",tabindex:"-1"},[c("社交媒体上实现增长的最佳途径（从零粉丝和零经验开始） "),e("a",{class:"header-anchor",href:"#社交媒体上实现增长的最佳途径-从零粉丝和零经验开始","aria-label":'Permalink to "社交媒体上实现增长的最佳途径（从零粉丝和零经验开始）"'},"​")],-1)),m(o),p[1]||(p[1]=h('<p>我一直梦想成为一名 YouTube 创作者 (YouTuber)。</p><p>但在看到一丝成功的曙光之前，我失败了好几年。</p><p>这就是我想在这封信里谈论的内容：</p><ul><li>我为什么失败（以及你能学到什么）</li><li>即使你缺乏自信、不是十分完美的超级模特，该如何开始</li><li>如何利用他人的权威来建立你自己的权威（这将带来最快的增长）</li><li>为什么把社交媒体当作电子游戏来对待是获得成功的关键（这将带来可持续的增长）</li></ul><p>在高中时，我放学回家后会去健身房，晚上就会看那些健身创作者如何以自己热爱的事情为生。</p><p>这些创作者就像是我连我是谁都不知道的朋友。</p><p>他们没有意识到他们对我的未来产生了多大的影响。</p><p>他们完全不知道，我这个身处完全不同地方的家伙，正在执行他们的建议，模仿他们的举止和行话，并正在成为一个不再受我成长环境所摆布的人。</p><p>社交媒体的负面影响显而易见。</p><p>但很少有人谈论，找到那些让你产生深深共鸣、并且正在做着你这辈子想做的事情的人，是如何改变你的人生的。</p><p>如果你完全不知道自己这辈子想做什么，你可以找到那些正在做着你曾经认为不可能的事情的创作者（因为你曾以为自己想做的只是上大学，拿个能保证高薪工作的学位）。</p><p>难怪美国有 30% 的儿童和 54% 的成年人说他们想把成为 YouTube 创作者当成一种职业。</p><p>这不是什么妄想出来的抱负。这是进化把我们引向的结果。人们想做自己热爱的事情，当你拨开层层表象，发现社交媒体的本质到底是什么——一种让任何人都能为自己热爱的工作吸引受众的方式——你就会意识到，这是一条几乎所有人都可以走、可以用来塑造未来的道路。</p><p>工作正在数字化。教育正在数字化。商业正在数字化。社会正在数字化。随着自动化和人工智能 (AI) 颠覆了我们认为安全稳妥的一切，我们在社交媒体上度过的第二人生预示着某种更为宏大的变迁。</p><p>交流、教育、价值、意义，以及作为人类的含义，都已然进化了。</p><p>如果你正在阅读这篇文章，我猜是因为你看到了这种潜力。记住，不是每个人都订阅了这个邮件列表。千万别以为每个人都有这种心态。</p><p>不，所有的工作并不会很快消失。而且我猜你渴望在工作之外做自己热爱的事情。所以，在社交媒体上建立受众群体，可以说是你能走的最稳妥的道路。</p><p>在我们开始之前，说个事，我们的作家训练营 (Writer&#39;s Bootcamp) 名额在4天内就售罄了。如果你错过了，请在<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">这里加入候补名单</a>等待下一期。（如果你错过了这期，没有任何例外）。</p><h2 id="_1-从写作开始" tabindex="-1">1) 从写作开始 <a class="header-anchor" href="#_1-从写作开始" aria-label="Permalink to &quot;1) 从写作开始&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>我未能实现成为 YouTube 创作者的梦想。</p><p>为什么？</p><p>因为我根本不知道自己在做什么。</p><p>我实际上从未学过那些构成社交媒体技能的子技能。是的，社交媒体是一项包含了说服力、营销、销售和心理学的综合技能。</p><p>这也是大多数人没能做到的……在你每次创作内容时，设身处地站在读者的角度思考。</p><p>我发布过关于心态、饮食挑战和健身日常的口播视频。</p><p>这几乎是7年前的事了。</p><p>我以为只要发布内容就这么简单。大错特错。</p><p>随着时间的推移，我尝试过大多数商业模式并以失败告终（比如一件代发、客户代运营、品牌建设、SEO、数字艺术和摄影）。</p><p>我在自由网页设计方面取得了一点小成功，足以让我辞掉工作，也正是那时我发现了推特 (Twitter)。</p><p>长话短说：</p><ul><li>我看到别人在没有手动外拓或投放广告的情况下，建立起了受众群体并获得了网页设计客户。</li><li>我注意到他们并不只是谈论网页设计。他们在谈论自己的生活方式、兴趣，<em>以及</em>网页设计（或者任何你想变现的技能）。</li><li>我注意到让他们与众不同的不是他们企业的价值主张，而是他们的个性。他们兴趣和观点的独特融合。</li><li>我注意到 Twitter 是以写作为基础的。他们没有把时间花在视觉效果或视频剪辑上。他们不必展示自己的身材。他们是用自己的想法，而不是外貌来建立业务。</li><li>我研究了他们在做的事情，并意识到我也能写出同样的内容。我有非常相似的知识储备，是什么阻碍了我去做他们正在做的事？（提示：是我自己的限制性信念）。</li></ul><p>于是，我迈出了这一步。</p><p>每次我看到一篇<em>我本来也可以写</em>的帖子时，我就会把它拿过来，用我自己的观点把它写出来。</p><p>每次我看到一篇我不同意的帖子，我就会把它拿过来，写下我自己对这个话题的看法。</p><p>每次我看到一篇结构很好（有项目符号、钩子、分行和流畅度）的帖子，我就会用这种结构做实验，把我自己的一条想法套进去。</p><p>换句话说，我留意了什么是行之有效的，并照着做。</p><p>我东学一点西学一点上了一些课程，并对这些策略进行了实验。</p><p>在第一年，我获得了10,000名粉丝（这对大多数人来说都是可行的）。</p><p>然后，复利增长开始显现，在近5年的时间里，我的粉丝数增长到了435,000名。</p><p>起初什么也没发生，然后一切接踵而至。</p><h2 id="_2-选择掌控你的增长" tabindex="-1">2) 选择掌控你的增长 <a class="header-anchor" href="#_2-选择掌控你的增长" aria-label="Permalink to &quot;2) 选择掌控你的增长&quot;">​</a></h2><p>我在 YouTube 上失败的第二个原因，是因为我喜欢谈论我想谈论的话题，而不是算法希望我谈论的话题。</p><p>当我发现写作和 Twitter 的力量时，我意识到，这可能是我最终在 YouTube 上获得增长的路径。</p><ul><li>YouTube 没有私信功能，也没有人们真正会去点的转发按钮（很难手动控制流量）。</li><li>Twitter 有私信、论坛式的回复、无阻力且受鼓励的转发机制，以及引用帖子的功能。</li><li>YouTube 需要大量的技能和精力来搞定视频制作中所有错综复杂的环节。</li><li>Twitter 就像花2-3分钟写个帖子然后点击发送一样简单。</li></ul><p>我在<a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">这里谈论了在社交媒体上实现增长的唯一方法</a>。那篇文章详细探讨了你可以用来博弈并获取增长的所有机制。</p><p>通过写作，我能够快速测试各种想法，并让我的网络人脉去分享它们。通过写作，我得以掌控自己的增长。</p><p>我意识到，如果我能用 Twitter 建立起受众群体，当准备好认真经营 YouTube 时，我就可以把这些受众引流过去。</p><p>既然现在 YouTube 是我最大的平台之一，人们就以为我是从那里起步的……而实际上，只有先在 Twitter 上起步，我才可能获得增长。</p><p>不仅如此，用制作一个视频的时间写出50条推文，这股力量是强大的。</p><p>这50条推文中必定有1条会是个好点子。</p><p>如果你没有一个好点子去拍摄，那么制作1个视频就不值得……它的数据表现不会好的。</p><p>因此，通过在 Twitter 上写作，你建立了一个好想法的数据库，你可以把它们<em>转化成</em>高表现的 YouTube 视频。只需围绕那条推文的主题制作视频即可。</p><p>虽然 Twitter 可能会慢慢成为我受众规模最小的平台，但它仍然拥有质量最高的受众，那是我起步的地方，如果没有它，我就无法建立起我其他的受众群体。没有其他任何一个社交平台能让你以如此充满人情味的方式来测试想法和进行互动……我是说，你去看看 Instagram 上的评论。甚至连个头像都没有。感觉乏味且毫无生气。你上 Instagram 是为了麻痹你的大脑，而不是拓展它。而 Twitter 感觉就像一场对话。</p><h2 id="_3-成为思想的-dj" tabindex="-1">3) 成为思想的 DJ <a class="header-anchor" href="#_3-成为思想的-dj" aria-label="Permalink to &quot;3) 成为思想的 DJ&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>作家就是玩转思想的 DJ。</p><p>DJ 从多个来源提取歌曲和声音，来创造出全新的东西。</p><p>作家从多个来源提取想法，并将它们串联起来，变成属于自己的东西。</p><p>你的社交媒体账号就是你的 Spotify 个人主页，而你的工作就是发行值得一听的音乐。</p><p>EDM（电子舞曲）或数字音乐的绝妙之处在于它没有限制。可以播放无数种混音组合。写作也是如此。</p><p>艺术家们重新混音彼此的歌曲，从而彻底改头换面。</p><p>这一点很重要。</p><p>无论是艺术家、DJ 还是制作人，都有属于他们自己的“标志性声音”。</p><p>我们都因为那种声音而喜欢上某些艺术家。</p><p>在 EDM 领域，Excision 和 RZRKT 非常相似，但他们之间微小的差异让彼此独一无二。</p><p>试想，如果 Excision 创作了一首乡村歌曲，我很难相信他的大部分粉丝会去听。他们想听的是纯正的 Excision 风格。</p><p>作为一名作家，你的“声音”就是你的世界观。</p><p>你的声音，就是你的想法如何透过你的目标、问题和经验的视角被表达出来。</p><p>这就是为什么你就是那个细分领域。</p><p>你收集和综合的所有想法都应该从你的世界观出发来写。</p><p>两个人都可以采用个人责任这个概念，并用两种不同的方式来构建它。</p><p>有情绪管理问题的人，会为了解决那个问题而写关于个人责任的内容。</p><p>有商业目标的人，会为了达成那个目标而写关于个人责任的内容。</p><p>你就是这样把别人的想法变成你自己的想法。</p><p>不要抄袭，要重新混音 (remix)。</p><h2 id="_4-利用权威做杠杆" tabindex="-1">4) 利用权威做杠杆 <a class="header-anchor" href="#_4-利用权威做杠杆" aria-label="Permalink to &quot;4) 利用权威做杠杆&quot;">​</a></h2><p>当你作为一个没有经验也没有权威的新手时，你要如何成长？</p><p>先策展，后创造。</p><p>利用他人的想法和权威来启动你的增长。</p><p>实现可持续增长的唯一途径，就是把人们从他们本来在的地方，吸引过来成为你的受众。</p><p>他们在哪里？</p><p>在别人的受众群体里。</p><p>你知道为什么人们会制作关于其他热门 YouTube 创作者的 YouTube 视频吗？是为了让那个视频能被推荐给那批受众，从而吸引他们观看。</p><p>你知道为什么大多数 YouTube 视频的标题听起来都很像吗？因为他们试图出现在那些<em>带有</em>该标题的热门视频的“推荐视频”板块里。</p><p>你知道为什么人们会告诉你多去别人的帖子下评论吗？因为他们的受众会点进回复区，看到你（希望是精彩而非无聊的）回复，然后关注你。</p><p>你需要把你的帖子展示给别人的受众看，而不是依赖算法来传播它们。</p><p>有几种方法可以做到这一点：</p><ul><li>写写他们的想法并标记他们。人们喜欢你引用他们的话，并且会乐意把你的帖子分享给他们的受众。</li><li>创作一条包含其他人多个想法的主题帖并把他们都标记出来。有些人会转发你，大多数人会参与互动。</li><li>针对一位有权威的人士写一篇帖子，利用他们最棒的想法来创作出一篇高数据表现的帖子。</li></ul><p>下面是个例子：</p><p><img src="'+l+'" alt=""></p><p>这里的问题在于，Naval 或 Rogan 可能不会看到或转发那条主题帖。</p><p>所以，明智的做法是选择在平台上比较活跃的人来写。</p><p>如果你确实写了超级名人，你需要让你自己的人脉网络把这篇帖子分享给他们的受众，这样帖子的表现才会好。</p><p>我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 小时作家 (2 Hour Writer)</a> 课程中教授了这个策略，但我也会在未来某天的信件中写写这个话题。</p><h2 id="_5-掌握钩子-hooks-与话题" tabindex="-1">5) 掌握钩子 (Hooks) 与话题 <a class="header-anchor" href="#_5-掌握钩子-hooks-与话题" aria-label="Permalink to &quot;5) 掌握钩子 (Hooks) 与话题&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>在社交媒体上获得增长，并不像想写什么就写什么那么简单。</p><p>你 95% 的增长将源自两件事：</p><ul><li>选择正确的话题来写。</li><li>完善钩子以吸引人们阅读更多内容。</li></ul><p>你的 YouTube 视频、新闻通讯或长推文有多大价值并不重要。如果人们不点击阅读更多，它就不会被阅读。如果人们不在乎你在谈论什么，他们就不会点击。如果人们看不到它能给自己的生活带来什么好处，他们就不会点击。</p><p>社交媒体的增长不是线性的。</p><p>有时候，你可能一整周都看不到任何增长（特别是作为一个没有观众基础来创造持续增长的新手）。</p><p>有时候，你在几周内只能看到一点点增长。</p><p>但接着，一旦你集齐了神圣的三要素（主题、钩子、流量），你的粉丝就会在一天内翻倍。起初什么都没发生，然后一切都在瞬间发生。但大多数人没有耐心或技能，去熬过打造自己事业时的起起落落。</p><p>社交媒体的增长是随机的。你并不是在付广告费，让你的文章精准投放给你选择的特定受众群体。</p><p>所以，你需要选择一个广泛适用的主题。你需要假设95%阅读你内容的人都是新手。</p><p>即使你有特定的目标受众，这一套依然行得通。</p><p>与其写“作为创始人如何领导一支50人的团队”，不如写“让你从10万美元赚到500万美元的技能”，并用“领导一支50人的团队”作为框架，来包装你想要传授的经验。</p><p>这还是同一个核心理念，只是重新定位，以触达并教育更多的人。</p><p>你依然会吸引你的目标受众，但你同时也会吸引一个更大的受众群体，他们可以把你的作品传播给<em>更多</em>你的目标受众。内容过于具体可能弊大于利。我宁愿拥有10万名受众，其中1万名是我的目标受众，也不愿受众里仅仅只有1万名目标群体。前者有更多的杠杆、触达率和机会。</p><p>当你选择了合适的主题，写钩子就会变得很简单。如果钩子很难写，你或许应该在投入大量时间写作之前换一个主题。</p><p>你该如何写出好钩子？</p><ul><li>检查你的文章，找出最有冲击力的部分并记下来</li><li>暗示一种通过解决痛点和带来好处而产生的转变，以此来开启好奇心闭环和信息差</li><li>使用概念、大想法和流程（比如艾森豪威尔矩阵或一人企业）来制造出某种独特机制的效果</li><li>尝试为实现该结果设定一个时间框架，比如2小时、30天或6个月</li><li>重点：研究其他人的钩子，给你的大脑编程，让它习惯用这种结构去思考</li></ul><p>现在，把这些当作一份清单，用来完善你的钩子：</p><ul><li><strong>相关性</strong> — 它与受众的日常生活有多大关联？解决的痛点或潜在的收益。读者能从中得到什么？</li><li><strong>认知度</strong> — 对于你瞄准的认知水平，它是足够简单还是足够复杂？他们能理解你准备向他们展示的内容吗？</li><li><strong>付出</strong> — 他们获得结果（教育、娱乐或启发）的速度有多快？获取起来容易吗？</li></ul><p>下次你在写长推文钩子、单条推文、YouTube 标题、封面文字或电子邮件主题时，把这套流程再过一遍。</p><h2 id="_6-全球电子游戏" tabindex="-1">6) 全球电子游戏 <a class="header-anchor" href="#_6-全球电子游戏" aria-label="Permalink to &quot;6) 全球电子游戏&quot;">​</a></h2><p>社交媒体既是一个多人在线游戏，又带有单人任务。</p><p>作为一个单人玩家，你必须不断增加你的技能储备。你至少应该对开展一项业务所需的每一项技能都有个大概的了解。营销、销售、网页设计、平面设计、视频剪辑、写作、营销、产品等等。狂刷超过75个小时的 YouTube 是必修课。</p><p>除此之外的一切，都是多人游戏。</p><p>你需要他人的受众群体来实现增长。</p><p>你需要别人来对你进行问责监督。</p><p>你需要一个部落，让人们在数字社会（社交媒体）中能够把你和它联系起来。</p><p>你需要重现你团队的语音频道，来确认敌人的位置，分享策略，并帮助你的团队赢下比赛。</p><p>你需要一个智囊团 (mastermind)：</p><p>多个大脑为了一个共同目标而努力。</p><p>在实际操作中，你需要：</p><ul><li>给你想要“组队”的人发私信</li><li>在那些你想要与之产生关联的人的帖子下留言评论</li><li>与他人建立群聊来分享策略</li><li>互相转发彼此最棒的帖子，给它们带来更多流量</li></ul><p>这应该被视为少数几种能在不依赖算法的情况下，<em>掌控</em> 你自身增长的方法之一。</p><p>这就创造了一个部落。</p><p>当你登录社交媒体，看到一个你喜欢的账号时，你通常也能想到另外 4-5 个与之相关且你同样喜欢的人。</p><p>人们关注那个部落是因为他们想要加入它。他们也想朝着那个目标努力。</p><p>这并不像你加入的那些浅薄的“互赞群”那样。这是你的互联网朋友圈，它是打造你理想企业的必需品。</p><p>这封信到这里就结束了。</p><p>感谢你的阅读，希望对你有帮助。</p><p>下周见，</p><p>– Dan</p><hr><p><a href="/en/letters/the-best-way-to-grow-on-social-media-from-zero-followers-experience">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',140))])}const q=i(d,[["render",b]]);export{Y as __pageData,q as default};
